INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10177, 217, 'tt0367882', NULL, 'Indiana Jones and the Kingdom of the Crystal Skull', 'Indiana Jones and the Kingdom of the Crystal Skull', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/56As6XEM1flWvprX4LgkPl8ii4K.jpg', 'https://image.tmdb.org/t/p/original/p96949hcwUG2BwE6MgKmw0uYNCx.jpg', 'Set during the Cold War, the Soviets—led by sword-wielding Irina Spalko—are in search of a crystal skull which has supernatural powers related to a mystical Lost City of Gold. Indy is coerced to head to Peru at the behest of a young man whose friend—and Indy''s colleague—Professor Oxley has been captured for his knowledge of the skull''s whereabouts.', NULL, NULL, 13.371, 6.029, 0, 9.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10178, 50153, 'tt0043778', NULL, 'The Man from Planet X', 'The Man from Planet X', 'movie', 1951, 'https://image.tmdb.org/t/p/w500/bA8TbHq96DaWxml0j3OneCBjrJG.jpg', 'https://image.tmdb.org/t/p/original/6QlHa9BaC2CTcfzCgqeyGRVwlYr.jpg', 'While watching for a planet that may collide with earth, scientists stationed in Scotland are approached by a visitor from outer space.', NULL, NULL, 1.1112, 5.851, 0, 8.05, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
