INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10180, 11549, 'tt0049366', NULL, 'Invasion of the Body Snatchers', 'Invasion of the Body Snatchers', 'movie', 1956, 'https://image.tmdb.org/t/p/w500/8BrMQmgwGzIHSyBjCDOLOdi79fJ.jpg', 'https://image.tmdb.org/t/p/original/qcLHMO01oECjbL8MUPRXsLOMFhx.jpg', 'A small-town doctor learns that the population of his community is being replaced by emotionless alien duplicates.', NULL, NULL, 4.8038, 7.459, 0, 9.03, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10181, 20410, 'tt0253658', NULL, 'Scooby-Doo and the Alien Invaders', 'Scooby-Doo and the Alien Invaders', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/f5E440uHsNU9XTfyK8KXYbRJGVo.jpg', 'https://image.tmdb.org/t/p/original/4COXzXt4axwGNxOK90KJ3YD8lM9.jpg', 'A cosmic case of flying saucers, intergalactic intrigue and out-of-this-world romance launches Scooby-Doo! and the Mystery Inc., Gang into their most unearthly adventure ever.', NULL, NULL, 3.0365, 7.113, 0, 6.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10182, 2432, 'tt0289830', NULL, 'Taken', 'Taken', 'tv', 2002, 'https://image.tmdb.org/t/p/w500/dFMBPZvgbvhnpCW8YfYakNB2xrT.jpg', 'https://image.tmdb.org/t/p/original/85VdFnoD33M9H2QW43QVOnpnKxU.jpg', 'The show takes place from 1944 to 2002 and follows the lives of three families: the Crawfords, who seek to cover up the Roswell crash and the existence of aliens; the Keys, who are subject to frequent experimentation by the aliens; and the Clarkes, who sheltered one of the surviving aliens from the crash.', NULL, NULL, 9.1271, 7.475, 0, 6.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10183, 11935, 'tt0077294', NULL, 'Capricorn One', 'Capricorn One', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/bxsCARg2rxQ2PzFW5ZsADLT9e9c.jpg', 'https://image.tmdb.org/t/p/original/d4qAHbs8wLBnRatYCPvtp3F48bO.jpg', 'In order to protect the reputation of the American space program, a team of NASA administrators turn the first Mars mission into a phony Mars landing. Under threat of harm to their families the astronauts play their part in the deception on a staged set in a deserted military base. But once the real ship returns to Earth and burns up on re-entry, the astronauts become liabilities. Now, with the help of a crusading reporter, they must battle a sinister conspiracy that will stop at nothing to keep the truth hidden.', NULL, NULL, 4.1057, 6.784, 0, 6.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10184, 12487, 'tt0361668', NULL, 'Gozu', '極道恐怖大劇場 牛頭 GOZU', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/mo5L0XzMYmLhdsvgA40qlYiHhAF.jpg', 'https://image.tmdb.org/t/p/original/fQOFjdWCMDnYujXlDuGBmNhV4i1.jpg', 'Minami mistakenly kills a gangster associate of his named Brother. Almost as soon as the murder takes place, the body of the deceased man is gone, prompting Minami to conduct a search. While looking, he finds a mysterious isolated hotel where he decides to take a rest. Not only are the front desk clerks a bit strange, but even the ambiance feels unusual. Minami soon realizes he may have gotten more than he bargained for.', NULL, NULL, 2.3676, 6.8, 0, 10.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10185, 422128, 'tt4607722', NULL, 'Blame', 'Blame', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/upAYxsju9jV7hU3k7pxYtS4exyL.jpg', 'https://image.tmdb.org/t/p/original/2O5dmxqbvJHIEZpszmt5sVGwW6F.jpg', 'A drama teacher''s taboo relationship with an unstable student strikes a nerve in her jealous classmate, sparking a vengeful chain of events within their suburban high school that draws parallels to "The Crucible".', NULL, NULL, 1.7066, 6.617, 0, 1.13, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10186, 17189, 'tt0107061', NULL, 'Battle Angel', '銃夢', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/urvznwew7HrjrIEbK2RLaEkaezs.jpg', 'https://image.tmdb.org/t/p/original/hf1huOYmOGlahJqGHSLpy4VetGo.jpg', 'In his travels as a bounty hunter, Hunter–Warrior and cyborg healer Ido one day discovers and repairs the remnants of a cyborg whom he names Gally. Though possessing the body of a young woman, Gally now embodies Ido''s most sophisticated and lethal cybernetic skills. The preternaturally strong, amnesiac Gally begins to forge a life for herself in a world where every day is a struggle for survival.', NULL, NULL, 2.2308, 6.844, 0, 1.05, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10187, NULL, NULL, 19817, 'Scorn', 'Scorn', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4v5c.jpg', NULL, 'Scorn is an atmospheric first person horror adventure game set in a nightmarish universe of odd forms and somber tapestry. It is designed around an idea of "being thrown into the world". Isolated and lost inside this dream-like world you will explore different interconnected regions in a non-linear fashion. The unsettling environment is a character itself. Every location contains its own theme (story), puzzles and characters that are integral in creating a cohesive lived in world. Throughout the game you will open up new areas, acquire different skill sets, weapons, various items and try to comprehend the sights presented to you.', 'https://www.igdb.com/games/scorn', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10188, NULL, NULL, 361880, 'Zero Parades: For Dead Spies', 'Zero Parades: For Dead Spies', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobpcd.jpg', NULL, 'From ZA/UM comes ZERO PARADES: For Dead Spies – a story-rich espionage RPG. You''re a brilliant but tormented operant on a desperate assignment. Pick up the pieces of your broken network, untangle a bloody web of intrigue at the End of History, and prove yourself on the big stage or blow it all up – again.', 'https://www.igdb.com/games/zero-parades-for-dead-spies', '["PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10189, 61909, 'tt0116503', NULL, 'Head of the Family', 'Head of the Family', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/lAfG6BBbnQE4PjTCziqId3BeBZ8.jpg', 'https://image.tmdb.org/t/p/original/kM0RV67DuQAiSkMemXejrUnKWj.jpg', 'In the midst of a torrid affair, Lance discovers that Nob Hollow''s weirdest residents, the Stackpoole family, have been doing hideous human experiments in the bowels of their basement.', NULL, NULL, 1.2996, 5.485, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10190, 316152, 'tt1124037', NULL, 'Free State of Jones', 'Free State of Jones', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/fTB6p9QwPRKIuK5LtB5CZXlkx5b.jpg', 'https://image.tmdb.org/t/p/original/crVDxx9KgNW7Bm1wyXqBYpzG2TS.jpg', 'In 1863, Mississippi farmer Newt Knight serves as a medic for the Confederate Army. Opposed to slavery, Knight would rather help the wounded than fight the Union. After his nephew dies in battle, Newt returns home to Jones County to safeguard his family but is soon branded an outlaw deserter. Forced to flee, he finds refuge with a group of runaway slaves hiding out in the swamps. Forging an alliance with the slaves and other farmers, Knight leads a rebellion that would forever change history.', NULL, NULL, 4.1668, 6.777, 0, 8.55, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10191, 21128, 'tt0102592', NULL, 'One False Move', 'One False Move', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/x5xCkGw4jutMcc8nmWLKNzbDKht.jpg', 'https://image.tmdb.org/t/p/original/iwOolqARbddbajguEIxM2ClP3aw.jpg', 'Following a series of drug deals and murders, three criminals -- Fantasia, Ray Malcolm and Pluto -- travel from Los Angeles to Houston, finally arriving in a small Arkansas town to go into hiding. Two detectives from the LAPD, who are already on the case, contact the town''s sheriff, Dale Dixon, to alert him of the fugitives'' presence in the area. Underestimating Dixon, the criminals have no idea what they are about to face.', NULL, NULL, 2.2578, 6.7, 0, 8.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10192, 582913, 'tt8485364', NULL, 'The Room', 'The Room', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/bWyQwZziHh1DK9F59eqahZD8Upc.jpg', 'https://image.tmdb.org/t/p/original/snbRXbkzEpc35mFDlwUg41cN8aw.jpg', 'Kate and Matt discover that a part of their house can grant wishes. In the wake of two miscarriages, what they want most is a child.', NULL, NULL, 4.0847, 6.403, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10193, 940139, 'tt18272208', NULL, 'Here', 'Here', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/79euHUJJtfgeGU63ef38KtNjXEn.jpg', 'https://image.tmdb.org/t/p/original/zrms2WPltCxTPoiNFNPtTih6NMf.jpg', 'An odyssey through time and memory, centered on a place in New Jersey where—from wilderness, and then, later, from a home—love, loss, struggle, hope and legacy play out between couples and families over generations.', NULL, NULL, 4.8928, 6.484, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10194, 41032, 'tt0069316', NULL, 'The Stone Tape', 'The Stone Tape', 'movie', 1972, 'https://image.tmdb.org/t/p/w500/oNa0LrdaOCZUFmSJZviBHBoXepZ.jpg', 'https://image.tmdb.org/t/p/original/2b7lkEJ38ZHzYUaF6RIvN4L76XT.jpg', 'A research team from an electronics company move into an old Victorian house to start work on finding a new recording medium. When team member Jill Greeley witnesses a ghost, team director Peter Brock decides not only to analyse the apparition, which he believes is a psychic impression trapped in a stone wall (dubbed a "stone tape"), but to exorcise it too - with terrifying results...', NULL, NULL, 0.8944, 6.1, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10195, 2841, 'tt0344510', NULL, 'A Very Long Engagement', 'Un long dimanche de fiançailles', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/jZ3Ir3d69dsyxif8dTVh3DjKzKH.jpg', 'https://image.tmdb.org/t/p/original/vOpm4wQk5qIl8UepoKrpaloqaPC.jpg', 'Young Frenchwoman Mathilde searches for the truth about her missing fiancé, lost during World War I, and learns many unexpected things along the way. The love of her life is gone. But she refuses to believe he''s gone forever — and she needs to know for sure.', NULL, NULL, 4.2929, 7.325, 0, 21.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10196, 325385, 'tt4451458', NULL, 'Endless Poetry', 'Poesía sin fin', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/iJTWnSa3YOnD15zMME3ox9GP8XA.jpg', 'https://image.tmdb.org/t/p/original/40KIc8piqrF1kwM7l8aInuz3aD2.jpg', 'A portrait of the director’s young adulthood, set in the 1940s–1950s, in the electric capital city of Santiago. There, he decides to become a poet and is introduced, by destiny, into the foremost bohemian and artistic circle of the time.', NULL, NULL, 1.6397, 7.435, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10197, 87107, 'tt7721046', NULL, 'Los Espookys', 'Los Espookys', 'tv', 2019, 'https://image.tmdb.org/t/p/w500/zsngYcv6LXsaTzLqSFD1HRIwWYW.jpg', 'https://image.tmdb.org/t/p/original/j52dl6b9s7Sp58iaMdxoj2LyZTC.jpg', 'A group of friends turn their love for horror into a peculiar business, providing horror to those who need it, in a dreamy Latin American country where the strange and eerie are just part of daily life.', NULL, NULL, 5.682, 6.237, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
