INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10202, 10501, 'tt0138749', NULL, 'The Road to El Dorado', 'The Road to El Dorado', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/tQuqhUBACMcGqCvliHxpJreBfXC.jpg', 'https://image.tmdb.org/t/p/original/ciM5RFsBoWEj0tbwJy42Hr76iRd.jpg', 'Stowing away after a failed con, a pair of swindlers end up on El Dorado, the fabled "city of gold", where they quickly get in over their heads when they are mistaken as gods by the inhabitants.', NULL, NULL, 9.8579, 7.301, 0, 1.47314285714285713e+01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10203, 1818, 'tt0115243', NULL, 'Lexx', 'Lexx', 'tv', 1997, 'https://image.tmdb.org/t/p/w500/oSDZ9YpDvAbXxzbC3YdknfyBR3W.jpg', 'https://image.tmdb.org/t/p/original/6HCTF1qRwysB7Q5pJjPTTTY0spr.jpg', 'A Time Prophet predicted that Kai would be the one to destroy the divine order in the league of the 20,000 planets, someday that will happen, but not today. Today a cowardly security guard, an undead assassin, a female with a body designed for sex and a robot head madly in love with her all make up the crew of the spaceship Lexx, the most powerful weapon in the two universes.', NULL, NULL, 16.7965, 7.01, 0, 1.05, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10204, 43593, 'tt0464154', NULL, 'Piranha 3D', 'Piranha 3D', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/lMLS2OFBbNYMSB1ZbVp4q2S4zTU.jpg', 'https://image.tmdb.org/t/p/original/AF0PiDItegyUtlBGDMGlSQbtro.jpg', 'Each year the population of sleepy Lake Victoria, Arizona explodes from 5,000 to 50,000 residents for the annual Spring Break celebration. But then, an earthquake opens an underwater chasm, releasing an enormous swarm of ancient Piranha that have been dormant for thousands of years, now with a taste for human flesh. This year, there''s something more to worry about than the usual hangovers and complaints from locals, a new type of terror is about to be cut loose on Lake Victoria.', NULL, NULL, 7.929, 5.422, 0, 9.53, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10205, 40814, 'tt0087100', NULL, 'Crimes of Passion', 'Crimes of Passion', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/tstF6JMrZe75AdEAoPejwPrDfMA.jpg', 'https://image.tmdb.org/t/p/original/bcpHVeaATZnRtw27V6NxNr8csoN.jpg', 'Fashion designer Joanna Crane leads a double life. By night she is China Blue, a prostitute who''s attracted the attention of a sexually frustrated private detective, and a psychopathic priest in possession of a murderous sex toy.', NULL, NULL, 4.058, 6.256, 0, 8.52, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10206, 1235192, 'tt27040807', NULL, 'Wormtown', 'Wormtown', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/lE10ww38b7XA5LIagIsVQj9a8Hn.jpg', 'https://image.tmdb.org/t/p/original/wfGDy0KVZsiQpGgYoxObUGgccwk.jpg', 'One year into a plague of flesh-eating, mind-altering worms, the nocturnal town of Ashland, Ohio, has embraced the parasites’ rule. Under cult-like Mayor Joshua, zealous Ranchers spread their gospel—by persuasion or by force. A trio of uninfected women cling to survival through scavenging, extreme hygiene, and evasion. But everyone breaks eventually, unleashing betrayal, sacrilege, and body horror.', NULL, NULL, 6.1762, 5.775, 0, 7.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10207, 44587, 'tt0118200', NULL, 'X', 'X -エックス-', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/irv0rrd34VGdxHRjI3AiJiXnAdo.jpg', 'https://image.tmdb.org/t/p/original/nMfRuH0WOdl4UVn4t3BK4GlcJ1m.jpg', 'It''s the year of destiny, and 15 year old Kamui Shiro, a powerful psychic, has returned to Toyko after a 6 year absence, having left when he was very young. He wants to be with his childhood friends, Fuma (his best friend) and Kotori, Fuma''s little sister (and Kamui''s possible girlfriend). He wants to protect them from all dangers, but destiny and fate are haunting Kamui and pulling in himself and his beloved childhood friends. It is his destiny and his sole decision to decide the fate of the world, no matter if he wants the role or not. Now it is a matter of if he will join the side of the Seven Seals and become the Dragon of Heaven to save mankind or join the Seven Angels and become the Dragon of Earth to destroy all civilization so the earth can heal itself from man''s destruction.', NULL, NULL, 3.1287, 6.093, 0, 7.51, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10208, 40342, 'tt0090930', NULL, 'Demons 2', 'Dèmoni 2… L''incubo ritorna', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/gAJGt3E6hoL9wRJodpoAKFaXHXd.jpg', 'https://image.tmdb.org/t/p/original/fZysWhyBOXND2oO5FdDuLBVjwpB.jpg', 'A group of tenants and visitors are trapped in a 10-story high-rise apartment building infested with demons who proceed to hunt the dwindling humans down.', NULL, NULL, 2.3306, 6.1, 0, 7.51, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10209, 424783, 'tt4701182', NULL, 'Bumblebee', 'Bumblebee', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/fw02ONlDhrYjTSZV8XO6hhU3ds3.jpg', 'https://image.tmdb.org/t/p/original/hMANgfPHR1tRObNp2oPiOi9mMlz.jpg', 'On the run in the year 1987, Bumblebee finds refuge in a junkyard in a small Californian beach town. Charlie, on the cusp of turning 18 and trying to find her place in the world, discovers Bumblebee, battle-scarred and broken.  When Charlie revives him, she quickly learns this is no ordinary yellow VW bug.', NULL, NULL, 11.4572, 6.721, 0, 10.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10210, 1063, 'tt0423731', NULL, 'Samurai Champloo', 'サムライチャンプルー', 'tv', 2004, 'https://image.tmdb.org/t/p/w500/lYpHeSm7BcUxAbBx1ucuEH7oGAe.jpg', 'https://image.tmdb.org/t/p/original/zsRvBsAVcJYz8wjpZnitMJz7HYr.jpg', 'Break-dancing but fierce warrior Mugen has to deal with the cold-blooded and conceited Jin, a samurai who believes he is above all. These sworn enemies are brought together by Fuu for a special task.', NULL, NULL, 13.3427, 8.301, 0, 9.65, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10211, 294682, 'tt3474600', NULL, 'Little Forest: Summer/Autumn', 'リトル・フォレスト 夏・秋', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/qDcoxRjv1bH29Hy8iTyOW1UnW9y.jpg', 'https://image.tmdb.org/t/p/original/1bAE9YexmEfAanXKaO1d9Ms4qKm.jpg', 'Fleeing heartbreak in the big city, Ichiko returns to Komori, her rural hometown. She battles summer''s rain and humidity, bakes her own bread, grows hothouse tomatoes and tills the fields. During autumn, the time for pickling and preserving fish and sweet potatoes, Ichiko begins reaping rice and recalls her departure five years before.', NULL, NULL, 3.1052, 7.77, 0, 8.53, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10212, 19616, 'tt0335762', NULL, 'Trick', 'トリック', 'tv', 2000, 'https://image.tmdb.org/t/p/w500/hbF3vrzwt6SW6CW8ziP5lZqZiCG.jpg', 'https://image.tmdb.org/t/p/original/p0MV7ijfbLG5Wu2HJXyoWgzVmo4.jpg', 'Although 23 year old Yamada Naoko is a "super" magician, she is continously fired and constantly hounded by her landlady for the rent being late. After being fired once again, her boss shows her an ad of a physics professor, a non-believer of all things magical, offering money to anyone who can prove to him that magic is real. Desperately needing the money, Naoko accepts the challenge, which is how she comes to meet Professor Ueda. Falling prey to her simple magic tricks, Ueda is impressed, and enlists Naoko to help him uncover the tricks behind a local cult. Their hilarious antics, along with those of police officer Yabe, leads them onto further mysteries, all with tricks needing to be solved in sort of an "X-Files" meets "Scooby-Doo"...', NULL, NULL, 10.141, 7.24, 0, 7.54, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10213, 291351, 'tt3450900', NULL, 'The Sea of Trees', 'The Sea of Trees', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/gmVGIEfzxupZUTer1Z5n80CHFnD.jpg', 'https://image.tmdb.org/t/p/original/f4lMXJZgCAlxazlERC3TBqc68vs.jpg', 'In Japan''s Aokigahara Forest, a troubled teacher meets a mysterious lost stranger who takes him on a life-changing journey of love and redemption.', NULL, NULL, 5.4057, 6.192, 0, 9.025, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10214, 596881, 'tt10219146', NULL, 'Dwelling in the Fuchun Mountains', '春江水暖', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/4ZMUOVHqIuXlHHnbQ0gg0jPLIi0.jpg', 'https://image.tmdb.org/t/p/original/AsDanXphy2uvK227rIZP1BiUWEr.jpg', 'In the Chinese town of Fuyang, four brothers go about their day-to-day lives, their destinies shaped by love and challenges.', NULL, NULL, 1.2534, 7.3, 0, 8.05, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10215, 76294, 'tt0192213', NULL, 'Raining in the Mountain', '空山靈雨', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/gCwFM4nFM2o6Q7ES7JOBcyTc3wZ.jpg', 'https://image.tmdb.org/t/p/original/nAZtxTr5Rkfvj8Gj64WlRfWiJKo.jpg', 'In Ming Dynasty China, the retiring abbot of a Buddhist monastery invites two dignitaries to help him choose a successor, not suspecting that both of them have hired help to steal a priceless parchment kept in the temple.', NULL, NULL, 1.4085, 7.26, 0, 8.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10216, 68981, 'tt0108630', NULL, 'Temptation of a Monk', '誘僧', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/uWFeMROISLfwI0zrHwEqI0EcVFH.jpg', 'https://image.tmdb.org/t/p/original/bG6Kp2DojvG5C4xtcB1vryn8uSQ.jpg', 'Near the beginning of the Tang dynasty, in 7th century China, General Shi Yan-sheng is tricked into leaving the crown prince unguarded. The crown prince is murdered by one of his brothers who then becomes emperor. Shi retreats to a monastery, perhaps to hide, perhaps to plan a coup. When his loyal troops as well as the princess he desires are slain, he seeks refuge in a remote, abandoned monastery where an aged abbot schools him with practical, earthy teachings. The emperor''s forces pursue Shi: first a woman, then a general seek to overpower him with lust and might. Over the course of the film, the reds of battle give way to blues of meditation.', NULL, NULL, 2.0298, 5.692, 0, 7.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10217, 428501, 'tt6333056', NULL, 'City of Ghosts', 'City of Ghosts', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/c1RxAfjPsSWV1PxuxnJM9BXMTFP.jpg', 'https://image.tmdb.org/t/p/original/h3OIAsdCIBAiTifvtZtrWPoGhlX.jpg', 'With unprecedented access, this documentary follows the extraordinary journey of “Raqqa is Being Slaughtered Silently”—a group of anonymous citizen journalists who banded together after their homeland was overtaken by ISIS—as they risk their lives to stand up against one of the greatest evils in the world today.', NULL, NULL, 1.2175, 7.189, 0, 7.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10218, 55292, 'tt1533749', NULL, 'Shaolin', '新少林寺', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/stvd0u2Pmy2VjdZHbFIEvCwDzRV.jpg', 'https://image.tmdb.org/t/p/original/lewuyD46yg3pjZpxqMLwfudIwWz.jpg', 'China is plunged into strife as feuding warlords try to expand their power by warring over neighboring lands. Fuelled by his success on the battlefield, young and arrogant Hao Jie sneers at Shaolin''s masters when he beats one of them in a duel. But the pride comes before a fall. When his own family is wiped out by a rival warlord, Hao is forced to take refuge with the monks. As the civil unrest spreads and the people suffer, Hao and the Shaolin masters are forced to take a fiery stand against the evil warlords. They launch a daring plan or rescue and escape.', NULL, NULL, 3.8134, 6.842, 0, 6.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10219, 1389137, 'tt34662438', NULL, 'Komang', 'Komang', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/2RWweAPdSSFzsCtxvjydldneUM6.jpg', 'https://image.tmdb.org/t/p/original/o7kF3veRvsHB61WmD6BGj21P1UC.jpg', 'Fate brought together Ode, a young man from Buton with big dreams, and Ade, a wanderer from Bali. Like two souls in love, they believed that fate would one day unite them. However, their journey was hindered by the presence of another man who shared the same faith as Ade, and Ode had to go to Jakarta to pursue his dreams. Will fate ultimately bring Ode and Ade together?', NULL, NULL, 1.2083, 7.3, 0, 6.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10220, 973778, 'tt21810682', NULL, 'The End We Start From', 'The End We Start From', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/S9U0axheNakD9LQusEpFijDgSe.jpg', 'https://image.tmdb.org/t/p/original/nmU3WgYuv7TyCrImrVtYG2VB6U6.jpg', 'As London is submerged below floodwaters, a woman gives birth to her first child. Days later, she and her baby are forced to leave their home in search of safety. They head north through a newly dangerous country seeking refuge from place to place.', NULL, NULL, 3.1504, 5.8, 0, 1.06, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10221, 929, 'tt0120685', NULL, 'Godzilla', 'Godzilla', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/xJVl1I95StraYAwaNbBkVoWE2qA.jpg', 'https://image.tmdb.org/t/p/original/p2wRmV9WbzPLdgd1HoeqdZeuBXi.jpg', 'French nuclear tests irradiate an iguana into a giant monster that viciously attacks freighter ships in the Pacific Ocean. A team of experts, including Niko Tatopoulos, conclude that the oversized reptile is the culprit. Before long, the giant lizard is loose in Manhattan as the US military races to destroy the monster before it reproduces and it''s spawn takes over the world.', NULL, NULL, 8.944, 5.654, 0, 1.15, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10222, 36244, 'tt0142316', NULL, 'Rainy Dog', '極道黒社会', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/zQVopy34WweVuBdMXWWlzJ5G1V1.jpg', 'https://image.tmdb.org/t/p/original/hvsfKEFga6L0ew3Mx7bGx99Ru2s.jpg', 'A Japanese assassin stranded in Taiwan must take work from a local crime boss to make ends meet when suddenly a woman from his past delivers a son to him.', NULL, NULL, 0.9989, 6.758, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
