INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10224, 68067, 'tt0195517', NULL, 'All Summer in a Day', 'All Summer in a Day', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/ld3te6i65GQz9FtwHwG5jAG7eNp.jpg', NULL, 'Based on the story by Ray Bradbury. Set on a planet where the sun shines for just a few minutes once every nine years, this is a classic tale of suffering and forgiveness. A classroom full of young children are excited to hear that today the rain will stop. However, they are also resentful of a new classmate from Earth who remembers what it''s like to see the sun.  "This gripping, unsettling production softens the original story’s abrupt conclusion without diminishing its punch. A masterful work." - Booklist. Winner of a CINE Golden Eagle, and honored by Instructor Magazine as one of the 25 Best Films of the Year.', NULL, NULL, 0.9253, 7.042, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
