INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10234, 19738, 'tt0243558', NULL, 'Revolutionary Girl Utena: The Movie', '少女革命ウテナ アドゥレセンス黙示録', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/lx68azELlJyBx7KqRe0Hy9wj9AU.jpg', 'https://image.tmdb.org/t/p/original/8VRmHiIGbQxIJH8p30niFl78qSC.jpg', 'In a loose retelling of the Revolutionary Girl Utena TV series, Utena Tenjou arrives at Ohtori Academy, only to be immediately swept up in a series of duels for the hand of her classmate Anthy Himemiya and the power she supposedly holds. At the same time, Utena reunites with Touga Kiryuu, a friend from her childhood who seems to know the secrets behind the duels. Utena must discover those secrets for herself, before the power that rules Ohtori claims her and her friends, new and old.', NULL, NULL, 3.0185, 7.361, 0, 8.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10235, NULL, NULL, 30225, 'Kenshi', 'Kenshi', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coclf6.jpg', NULL, 'A free-roaming squad based RPG. Focusing on open-ended sandbox gameplay features rather than a linear story. Be a trader, a thief, a rebel, a warlord, an adventurer, a farmer, a slave, or just food for the cannibals. Research new equipment and craft new gear. Purchase and upgrade your own buildings to use as safe fortified havens when things go bad, or use them to start up a business. Aid or oppose the various factions in the world while striving for the strength and wealth necessary to simply survive in the harsh desert. Train your men up from puny victims to master warriors. Carry your wounded squad mates to safety and get them all home alive.', 'https://www.igdb.com/games/kenshi', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 8.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
