INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10238, 31858, 'tt0084287', NULL, 'Made in Britain', 'Made in Britain', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/8ygBME2MULEQVxqFZzBfje7Jnhz.jpg', 'https://image.tmdb.org/t/p/original/ozqCSHGpJz0cZmNS6yVFX0sWGMw.jpg', '16-year-old skinhead Trevor has no regard for authority, and would rather spend his time stealing cars than sitting in the detention centre to which he is sent. Social worker Harry Parker tries his best, but Trevor is only interested when there''s something in it for him. The centre authorities try to conform Trevor to the norms of society, but he takes no notice, and would rather speak in a torrent of four-letter words and racial abuse.', NULL, NULL, 1.3206, 7.001, 0, 9.04, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
