INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10240, 26579, 'tt0368774', NULL, 'The Heart Is Deceitful Above All Things', 'The Heart Is Deceitful Above All Things', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/gf5wCcEvCPhpLFZkY68aLzMNAfC.jpg', 'https://image.tmdb.org/t/p/original/kfjHG9n155YsOVwGKciB7q8KPAe.jpg', 'Young Jeremiah lives in a stable environment with loving foster parents until the day his troubled mother, Sarah, returns to claim him. Jeremiah becomes swept up in his mother''s dangerous world of drugs, seedy hotels, strip joints and revolving lovers. Salvation comes in the form of the boy''s ultrareligious grandparents, but soon Jeremiah''s mother returns. Maternal love binds the pair together on the road until Sarah''s desperate and depraved lifestyle finally consumes her.', NULL, NULL, 2.9143, 5.827, 0, 10.525, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
