INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10242, 105203, 'tt0280015', NULL, 'Violet Perfume: Nobody Hears You', 'Nadie te oye: perfume de violetas', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/gWuhAHj0vK4UNZvJZevxobkmGDq.jpg', 'https://image.tmdb.org/t/p/original/1fJZzkyOKNv4ExSf7uXQNUzycr9.jpg', 'Yessica is a rebellious girl who forms an unlikely friendship with quiet schoolmate Miriam. Yessica''s home life is ruled by her brutal stepfather and her amoral stepbrother, Jorge, while Miriam shares a calm, loving household with her mother. The girls'' friendship is shattered after Jorge arranges to have one of his friends rape Yessica.', NULL, NULL, 0.9377, 7.883, 0, 10.015, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10243, 995, 'tt0083435', NULL, 'The Kids of Degrassi Street', 'The Kids of Degrassi Street', 'tv', 1979, 'https://image.tmdb.org/t/p/w500/7aJ88ze08Q6i3on7H1DGQQOEFap.jpg', 'https://image.tmdb.org/t/p/original/gmpVVQSCLZ8UkjBISnxCAeziS80.jpg', 'The Kids of Degrassi Street is a Canadian children''s TV show that aired from 1979 to 1986, and is the first in the Degrassi series, about the lives of a group of children living on Degrassi Street in Toronto, Canada. It grew out of four short films: Ida Makes a Movie, Cookie Goes to the Hospital, Irene Moves In and Noel Buys a Suit, which originally aired as after-school specials on CBC Television in 1979, 1980, 1981 and 1982, respectively. The show was acclaimed for its realistic depiction of every day children''s lives and tribulations, and remains memorable to many Canadians because of this.

Kids of Degrassi Street featured many of the same actors who would later appear on Degrassi Junior High and Degrassi High, including Stacie Mistysyn, Neil Hope, Anais Granofsky, Sarah Charlesworth and others. However, their character names and families were different, so this series cannot technically be seen as an immediate precursor to the later shows.', NULL, NULL, 3.5259, 6.9, 0, 9.51, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10244, 3469, 'tt0061648', NULL, 'Far from the Madding Crowd', 'Far from the Madding Crowd', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/2cCHnpaf5JTRlgO07uulEdUpFkb.jpg', 'https://image.tmdb.org/t/p/original/fDeklBmKoeTUslH9uYtZRzWnXHs.jpg', 'Bathsheba Everdine, a willful, flirtatious, young woman, unexpectedly inherits a large farm and becomes romantically involved with three widely divergent men.', NULL, NULL, 1.578, 6.9, 0, 1.03, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10245, 2731, 'tt0104507', NULL, 'Indochine', 'Indochine', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/sAemRfr6mOSwtQ76e4yUQVImo8B.jpg', 'https://image.tmdb.org/t/p/original/sk5YqvIl4jd7xgw7lcoUMYOLjKt.jpg', 'In colonial Vietnam, dashing French naval captain Jean-Baptiste, wealthy plantation owner Éliane Devries, and her adopted Vietnamese daughter Camillevare form the three points of a cross-cultural romantic triangle. As the struggle against European imperialism sweeps Indochina, Jean-Baptiste and Camille have to choose sides and Éliane faces the emotionally difficult challenge of raising the child of her daughter and ex-lover.', NULL, NULL, 4.0373, 7.0, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
