INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10248, 532865, 'tt3661210', NULL, 'The Dig', 'The Dig', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/dFDNb9Gk1kyLRcconpj7Mc7C7IL.jpg', 'https://image.tmdb.org/t/p/original/wQhe2YJnB9AAS08RqwMeKN2ywUr.jpg', 'As WWII looms, a wealthy widow hires an amateur archaeologist to excavate the burial mounds on her estate. When they make a historic discovery, the echoes of Britain''s past resonate in the face of its uncertain future‎.', NULL, NULL, 4.1656, 6.836, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
