INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10251, 17909, 'tt0076276', NULL, 'Who''s Singin'' Over There?', 'Ко то тамо пева', 'movie', 1980, 'https://image.tmdb.org/t/p/w500/1r4buAPUyqWwhdKxki1fyBeehsw.jpg', 'https://image.tmdb.org/t/p/original/hL4J5AbITCkgiAE1VKx8bAemp0D.jpg', 'On Saturday, 5 April 1941, one day before the Invasion of Yugoslavia of the Kingdom of Yugoslavia, a colourful group of random passengers on a country road deep in the heart of Serbia board a dilapidated bus, headed for the capital Belgrade. The group includes two gypsy musicians, a World War I veteran, a Germanophile, a budding singer, a sickly looking man, and a hunter with a shotgun. The bus is owned by Krstic senior, and driven by his impressionable and dim-witted son Misko.', NULL, NULL, 1.287, 7.569, 0, 11.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
