INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10253, 7354, 'tt1232320', NULL, 'Harper''s Island', 'Harper''s Island', 'tv', 2009, 'https://image.tmdb.org/t/p/w500/ihpf4yvi9GWATXj7IApblIHRMP4.jpg', 'https://image.tmdb.org/t/p/original/s1bCQKRcJsJ0cQfYUTfH70PbHMI.jpg', 'A group of family and friends travels to a secluded island for a destination wedding. They''ve come to laugh... to love... and, though they don''t know it... to die. As the wedding festivities begin, friendships are tested and secrets exposed as a murderer claims victims, one by one, transforming the wedding week of fun and celebration into a terrifying struggle for survival.', NULL, NULL, 8.7234, 6.931, 0, 1.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
