INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10255, 1641, 'tt0141098', NULL, 'Forces of Nature', 'Forces of Nature', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/etmjiee84g6G9WALmLkJ1DhenAu.jpg', 'https://image.tmdb.org/t/p/original/lZYsPT5WzDMgHe4tZzO9GHVN9ei.jpg', 'Ben Holmes, a professional book-jacket blurbologist, is trying to get to Savannah for his wedding. He just barely catches the last plane, but a seagull flies into the engine as the plane is taking off. All later flights are cancelled because of an approaching hurricane, so he is forced to hitch a ride in a Geo Metro with an attractive but eccentric woman named Sara.', NULL, NULL, 4.5955, 5.457, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10256, 37664, 'tt1837654', NULL, 'The Secret Circle', 'The Secret Circle', 'tv', 2011, 'https://image.tmdb.org/t/p/w500/3MwvNMhD9xpf1exlSfWgVm4sOF5.jpg', 'https://image.tmdb.org/t/p/original/lYD41UqeRJohZ2nJnpwpSQJiCcj.jpg', 'After her mother dies in a fire, Cassie Blake moves in with her grandmother in the small town of Chance Harbor, Washington. As she gets to know her high school classmates, strange and frightening things begin to happen. They are all descended from powerful witches, and they''ve been waiting for Cassie to join them and complete a new generation of the Secret Circle. What they don''t yet know is that darker powers are at play and that Cassie''s mother''s death might not have been an accident.', NULL, NULL, 8.3088, 7.3, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
