INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10258, 207863, 'tt15428778', NULL, 'Mayfair Witches', 'Mayfair Witches', 'tv', 2023, 'https://image.tmdb.org/t/p/w500/eDl1veju2Hf3tyFmGAedtGXb9Yv.jpg', 'https://image.tmdb.org/t/p/original/9DHo5qXkG0titQmr2PF92N3aYYk.jpg', 'An intuitive young neurosurgeon discovers that she is the unlikely heir to a family of witches. As she grapples with her newfound powers, she must contend with a sinister presence that has haunted her family for generations.', NULL, NULL, 20.3884, 7.295, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10259, 23615, 'tt0084637', NULL, 'The Scarlet Pimpernel', 'The Scarlet Pimpernel', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/89jU2EH7ccpK6jDEJ6fO9bIe2RN.jpg', 'https://image.tmdb.org/t/p/original/1uBhI3YTROQBvm2pL8Lamus8NYv.jpg', 'During the French Revolution, a mysterious English nobleman known only as The Scarlet Pimpernel (a humble wayside flower), snatches French aristos from the jaws of the guillotine, while posing as the foppish Sir Percy Blakeney in society. Percy falls for and marries the beautiful actress Marguerite St. Just, but she is involved with Chauvelin and Robespierre, and Percy''s marriage to her may endanger the Pimpernel''s plans to save the little Dauphin', NULL, NULL, 2.35, 6.735, 0, 11.04, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10260, 41784, 'tt0101465', NULL, 'Black Robe', 'Black Robe', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/kaogaZD8WkwfRJnr7zvktiY5E2p.jpg', 'https://image.tmdb.org/t/p/original/7Gm9NXq1Ydje7uyx9Ogr1FxFkIa.jpg', 'Missionary Father LaForgue travels to the New World in hopes of converting Algonquin Indians to Catholicism. Accepted, though warily, by the Indians, LaForgue travels with the Indians using his strict Catholic rules and ideals to try and impose his religion.', NULL, NULL, 2.0967, 6.48, 0, 11.05, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10261, 9313, 'tt0120744', NULL, 'The Man in the Iron Mask', 'The Man in the Iron Mask', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/zHE9yRURvA7DyhYtQxkGTfE1Ywi.jpg', 'https://image.tmdb.org/t/p/original/uhhtglfXNaTavkKtjer38qHLfVi.jpg', 'Years have passed since the Three Musketeers, Aramis, Athos and Porthos, have fought together with their friend, D''Artagnan. But with the tyrannical King Louis using his power to wreak havoc in the kingdom while his twin brother, Philippe, remains imprisoned, the Musketeers reunite to abduct Louis and replace him with Philippe.', NULL, NULL, 6.0164, 6.656, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10262, 49249, 'tt0081595', NULL, 'A Tale of Two Cities', 'A Tale of Two Cities', 'movie', 1980, 'https://image.tmdb.org/t/p/w500/pwjalifg69dI9RCp6LDybF1qLAR.jpg', 'https://image.tmdb.org/t/p/original/nOZqNQX0OQmK8oVeRhAed1F2ecT.jpg', 'Set against the conditions leading up to the French Revolution and the Reign of Terror, French doctor Alexandre Manette serves an 18-year imprisonment in the Bastille in Paris, followed by his release to live in London with the daughter he has never met.', NULL, NULL, 1.3189, 6.143, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10263, 35196, 'tt0114272', NULL, 'Restoration', 'Restoration', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/glOCWK6AMl6FVHxLikl5OD8xw2B.jpg', 'https://image.tmdb.org/t/p/original/5uLnlBxEiy1rSK6Bqexa3gxzfYu.jpg', 'An aspiring young physician, Robert Merivel found himself in the service of King Charles II and saves the life of someone close to the King. Merivel joins the King''s court and lives the high life provided to someone of his position. Merivel is ordered to marry his King''s mistress in order to divert the queens suspicions. He is given one order by the king and that is not to fall in love. The situation worsens when Merivel finds himself in love with his new wife. Eventually, the King finds out and relieves Merivel of his position and wealth. His fall from grace leaves Merivel where he first started. And through his travels and reunions with an old friend, he rediscovers his love for true medicine and what it really means to be a physician.', NULL, NULL, 2.5501, 6.1, 0, 11.1, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10264, 3573, 'tt0116191', NULL, 'Emma', 'Emma', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/fM5goQ6c3uq3hzNJj3ZAFfTFkX9.jpg', 'https://image.tmdb.org/t/p/original/eBQc24VRzNXz3gFMrvdSvwd6Ire.jpg', 'Emma Woodhouse is a congenial young lady who delights in meddling in other people’s affairs. She is perpetually trying to unite men and women who are utterly wrong for each other. Despite her interest in romance, Emma is clueless about her own feelings, and her relationship with gentle Mr. Knightley.', NULL, NULL, 3.8325, 6.609, 0, 11.04, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10265, 14902, 'tt0068156', NULL, '1776', '1776', 'movie', 1972, 'https://image.tmdb.org/t/p/w500/o50REDExdajGxTWczsmC3qcawGr.jpg', 'https://image.tmdb.org/t/p/original/vNR2HcqGrIK1BX570en1SpzOYF7.jpg', 'Colonial representatives gather in Philadelphia with the aim of establishing a set of governmental rules for the burgeoning United States. Benjamin Franklin and John Adams charge Thomas Jefferson with the task of writing a statement announcing the new country''s emancipation from British rule.', NULL, NULL, 2.0987, 6.916, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
