INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10273, 10057, 'tt0108333', NULL, 'The Three Musketeers', 'The Three Musketeers', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/mk8UH7JRmK8adcqJJpB1ygP7B1C.jpg', 'https://image.tmdb.org/t/p/original/1M7eNvLkrAbhQDbcoBnVfzanHcT.jpg', 'D''Artagnan travels to Paris hoping to become a musketeer, one of the French king''s elite bodyguards, only to discover that the corps has been disbanded by conniving Cardinal Richelieu, who secretly hopes to usurp the throne. Fortunately, Athos, Porthos and Aramis have refused to lay down their weapons and continue to protect their king. D''Artagnan joins with the rogues to expose Richelieu''s plot against the crown.', NULL, NULL, 6.8816, 6.39, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
