INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10277, 13791, 'tt1050057', NULL, 'The Devil''s Whore', 'The Devil''s Whore', 'tv', 2008, 'https://image.tmdb.org/t/p/w500/xWUF0cERovge3CrTI646FX0CQbp.jpg', 'https://image.tmdb.org/t/p/original/5XGlfB967TwCXDdNWFqYxZML9hA.jpg', 'The Devil''s Whore is a four-part television drama serial produced by Company Pictures for Channel 4, broadcast from 19 November to 10 December 2008.

As the English Civil War rages, when both politics and religion divide the nation, spirited aristocrat Angelica Fanshawe is drawn to the anti-monarchist cause. She tells the story as England dares to execute its king and search for an alternative means of government.', NULL, NULL, 3.0534, 6.918, 0, 11.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
