INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10279, NULL, NULL, 1576, 'Spyro the Dragon', 'Spyro the Dragon', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3kmh.jpg', NULL, 'Spyro the Dragon is a platform game developed by Insomniac Games for the PlayStation. It stars the title character, a young purple dragon named Spyro and his dragonfly friend, Sparx, and is the first game in the Spyro the Dragon series. The first game was massively popular at its initial release and Spyro would later become one of the most recognizable, popular and respected gaming icons for the PlayStation gaming console. Spyro''s best friend, Sparx the dragonfly, acts like the player''s health meter and assists in gathering gems. The various dragons Spyro unfreezes along the way are also key characters in Spyro''s progression through the game. Gnasty Gnorc is the main antagonist, who froze all the dragons of the land in crystal.', 'https://www.igdb.com/games/spyro-the-dragon', '["PlayStation 3", "PlayStation", "PlayStation Portable"]', NULL, NULL, 0, 2.40500000000000024e+00, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10280, 69293, 'tt6352180', NULL, 'Little Witch Academia', 'リトルウィッチアカデミア', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/93Lz0LwbScZ5bmuqoIngLv1LKNb.jpg', 'https://image.tmdb.org/t/p/original/u9wiLQNyI3FBjyNnXJka56ndG2F.jpg', 'When she was a little girl, Atsuko "Akko" Kagari saw a magic show performed by a witch named Shiny Chariot.  From that day on she wanted to be just like her.  Enrolling at Luna Nova Magical Academy and having no magical background, can she become a witch like her idol Shiny Chariot?', NULL, NULL, 14.1629, 7.908, 0, 1.19, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10281, 1352660, 'tt28788767', NULL, 'The Town Without Halloween', 'The Town Without Halloween', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/49aGeKBBDFLKAtGknJmtEaiXr43.jpg', 'https://image.tmdb.org/t/p/original/rxjVm8QRvvkI4HFsFQvWuiiF7Z4.jpg', 'In a town immersed in Halloween traditions, a group of teens stumbles upon the Mayor''s scheme to abolish the beloved holiday. With dark powers at stake, they must save their community and Halloween itself in The Town Without Halloween.', NULL, NULL, 0.613, 2.5, 0, 1.05, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10282, 15016, 'tt0383206', NULL, 'Barbie of Swan Lake', 'Barbie of Swan Lake', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/jmMLTLGO6GMqmXLhj8kv0JcrMpt.jpg', 'https://image.tmdb.org/t/p/original/tonrulTmO9ZyZmsAsr5yr9ciE4c.jpg', 'Barbie as Odette, the young daughter of a baker, follows a unicorn into the Enchanted Forest and is transformed into a swan by an evil wizard intent on defeating the Fairy Queen.', NULL, NULL, 6.5959, 7.037, 0, 1.13, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10283, NULL, NULL, 2148, 'Banjo-Kazooie', 'Banjo-Kazooie', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobbr5.jpg', NULL, 'Trouble brews when Gruntilda the witch captures the unbearably beautiful cub, Tooty. But before the grisly hag can steal the bear''s good looks, big brother Banjo and his fine-feathered friend, Kazooie, join forces to stop her. Combining their 24 moves and special powers, Banjo and Kazooie will fend off armies of beasts. Bear and bird must hunt down the 100 puzzle pieces and 900 musical notes that will ultimately lead them to Gruntilda. However. miles of swamp, desert, and snow and one bear of an adventure stand in their way.', 'https://www.igdb.com/games/banjo-kazooie', '["Nintendo 64"]', NULL, NULL, 0, 1.05, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10284, NULL, NULL, 1187, 'Crash Bandicoot: Warped', 'Crash Bandicoot: Warped', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co873w.jpg', NULL, 'Crash Bandicoot: Warped is the third game in the Crash Bandicoot series and the first to feature Coco as a playable character. The player takes control of Crash and Coco Bandicoot, who must travel back and forward in time and gather 25 crystals before Uka Uka and Doctor Neo Cortex can do so. Much of the game takes place in the Time Twister which acts as the hub area of the game. The Time-Twister is split up into five chambers, each chamber has five buttons that open portals to different levels. The goal in each level is to find and obtain the crystal hidden in the level. Crash Bandicoot: Warped was lauded by critics in many areas, and the game has been considered one of the best video games of all time.', 'https://www.igdb.com/games/crash-bandicoot-warped', '["PlayStation 3", "PlayStation", "PlayStation Portable"]', NULL, NULL, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10285, NULL, NULL, 1801, 'Sly Cooper: Thieves in Time', 'Sly Cooper: Thieves in Time', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rbv.jpg', NULL, 'Sly Cooper: Thieves in Time is a stealth platformer developed by Sanzaru Games and published by Sony Computer Entertainment. Released in 2013 for PlayStation 3 and PlayStation Vita, it is the fourth main entry in the Sly Cooper series.

The game follows Sly and his gang as they travel through different historical periods to restore the Thievius Raccoonus, which is being erased from existence. Players control Sly and various characters, each with unique abilities while completing stealth-based missions, platforming challenges, and puzzles. The game retains the series’ signature cel-shaded art style and humour while introducing new mechanics, including time-travelling settings and costumes with special abilities.', 'https://www.igdb.com/games/sly-cooper-thieves-in-time', '["PlayStation 3", "PlayStation Vita"]', NULL, NULL, 0, 2.04, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
