INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10304, 641668, 'tt11188624', NULL, 'Seance', 'Seance', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/roYaaPorqPvazR0sh1aTl64Fjsu.jpg', 'https://image.tmdb.org/t/p/original/5lqXZh4X1dbX7stB4dF0xuBEpcT.jpg', 'At an elite boarding school for girls, six friends jokingly engage in a late night ritual, calling forth the spirit of a dead former student who reportedly haunts their halls. Before morning, one of the girls is dead, leaving the others wondering what they may have awakened.', NULL, NULL, 2.6964, 5.577, 0, 1.04, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10305, 158752, 'tt2187884', NULL, 'Escape from Tomorrow', 'Escape from Tomorrow', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/g3qZofBWiLauJviv27f8zpEFbki.jpg', 'https://image.tmdb.org/t/p/original/AtUC9rFuBE43QQ0JyORuHw6fqEi.jpg', 'In a world of fake castles and anthropomorphic rodents, an epic battle begins when an unemployed father''s sanity is challenged by a chance encounter with two underage girls on holiday.', NULL, NULL, 1.1309, 4.8, 0, 1.06, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
