INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10307, 36040, 'tt0067959', NULL, 'Walkabout', 'Walkabout', 'movie', 1971, 'https://image.tmdb.org/t/p/w500/24vooYt5StgtgcQObVr1GHuM5gy.jpg', 'https://image.tmdb.org/t/p/original/uA5GfPzRU1vRVY7pDfqXQmjRTPI.jpg', 'Under the pretense of having a picnic, a geologist takes his teenage daughter and 6-year-old son into the Australian outback and attempts to shoot them. When he fails, he turns the gun on himself, and the two city-bred children must contend with harsh wilderness alone. They are saved by a chance encounter with an Aboriginal boy who shows them how to survive, and in the process underscores the disharmony between nature and modern life.', NULL, NULL, 3.7639, 7.299, 0, 1.03, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
