INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10310, 61943, 'tt0062082', NULL, 'Django Kill... If You Live, Shoot!', 'Se sei vivo spara', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/6aFamqGpI5T7sl9pVKBf7pipeV.jpg', 'https://image.tmdb.org/t/p/original/3i1N1ZVbbuPHtSCcXs4bRBFxxqv.jpg', 'A Mexican outlaw known as "The Stranger" is part of a band of thieves that steal a cargo of gold from a stagecoach. However, the Americans in the band betray him, and shoot all the Mexicans. The Stranger is not completely dead though, and crawls his way out of his shallow grave, continuing his pursuit of the gold, and exacting a bloody vengeance.', NULL, NULL, 1.3488, 5.8, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
