INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10331, 31952, 'tt0066518', NULL, 'The Vampire Lovers', 'The Vampire Lovers', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/6MTiYnp62i2kdweHjhchwJscQrj.jpg', 'https://image.tmdb.org/t/p/original/wbherYlV9zGsivnNxzpldjkYkuC.jpg', 'In the heart of Styria the Karnstein Family, even after their mortal deaths, rise from their tombs spreading evil in the countryside in their lust for fresh blood. Baron Hartog whose family are all victims of Karnstein vampirism, opens their graves and drives a stake through their diabolical hearts. One grave he cannot locate is that of the legendary beautiful Mircalla Karnstein. Years of peace follow that grisly night until Mircalla reappears to avenge her family''s decimation and satisfy her desire for blood.', NULL, NULL, 3.2449, 6.378, 0, 1.26, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
