INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10333, 15566, 'tt0252028', NULL, 'Surviving Christmas', 'Surviving Christmas', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/8jHtvFpCOOqp2U2qwI3L3h10cUv.jpg', 'https://image.tmdb.org/t/p/original/7aRm8GSxrPhJK671kVADYgmJy7w.jpg', 'A wealthy executive, Drew Latham (Ben Affleck) has no close relationships and becomes nostalgic for his childhood home as Christmas approaches. When he visits the house and finds another family living there, he offers the residents, Tom Valco (James Gandolfini) and his wife, Christine (Catherine O''Hara), a large sum of money to pretend they are his parents. Soon Drew tests the couple''s patience, and, when their daughter, Alicia (Christina Applegate), arrives, things get increasingly tense.', NULL, NULL, 3.3521, 5.718, 0, 1.14000000000000012e+00, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
