INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10348, 63161, 'tt4094300', NULL, 'Crazy Ex-Girlfriend', 'Crazy Ex-Girlfriend', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/pvYh3fdrRvreWmqw4onWJJmRXf5.jpg', 'https://image.tmdb.org/t/p/original/5rNvv9UCAjDHi69OXvKD7bDxkf7.jpg', 'Rebecca Bunch is a successful, driven, and possibly crazy young woman who impulsively gives up everything - her partnership at a prestigious law firm and her upscale apartment in Manhattan - in a desperate attempt to find love and happiness in that exotic hotbed of romance and adventure: suburban West Covina, California.', NULL, NULL, 14.3194, 6.8, 0, 1.27066666666666652e+01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
