INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10350, 364540, 'tt3955894', NULL, 'Girl Asleep', 'Girl Asleep', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/yHmXk0j8RTKV9br3wEKCm9ApZag.jpg', 'https://image.tmdb.org/t/p/original/3VD3BseZJvAMagjTY9oH1bbQR8R.jpg', 'The world is closing in on Greta Driscoll. On the cusp of turning fifteen, she can’t bear to leave her childhood; it contains all the things that give her comfort in an incomprehensible new world. She floats in a bubble of loserdom with her only friend, Elliott, until her parents throw her a surprise fifteenth birthday party and she’s flung into a parallel place—a world that’s weirdly erotic, a little bit violent, and thoroughly ludicrous. Only there can she find herself.', NULL, NULL, 1.8671, 6.076, 0, 1.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
