INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10356, 11425, 'tt0119310', NULL, 'Honey, We Shrunk Ourselves', 'Honey, We Shrunk Ourselves', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/nbU3UgIjxNTrSSe2gcOSGQjf55a.jpg', 'https://image.tmdb.org/t/p/original/gIhLlTYILo2BP6xt2KeBNxQDN4E.jpg', 'The joke''s on absent-minded scientist Wayne Szalinski when his troublesome invention shrinks him, his brother and their wives so effectively that their children think they''ve completely disappeared. Of course, this gives the kids free rein to do anything they want, unaware that their parents are watching every move.', NULL, NULL, 3.7351, 5.434, 0, 9.05, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
