INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10358, 10202, 'tt0960731', NULL, 'Bedtime Stories', 'Bedtime Stories', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/rSOnWm8ahvgThYp8TKGRUTcvsyw.jpg', 'https://image.tmdb.org/t/p/original/gu9SE1fuuc5cA8w8om21lc4at3h.jpg', 'Skeeter Bronson is a down-on-his-luck guy who''s always telling bedtime stories to his niece and nephew. But his life is turned upside down when the fantastical stories he makes up for entertainment inexplicably turn into reality. Can a bewildered Skeeter manage his own unruly fantasies now that the outrageous characters and situations from his mind have morphed into actual people and events?', NULL, NULL, 9.2265, 6.15, 0, 7.52, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10359, 289450, 'tt4653310', NULL, 'Driving Miss Daisy', 'Driving Miss Daisy', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/lE1UzoV7gZhmqhw1qTiyyichPgh.jpg', 'https://image.tmdb.org/t/p/original/auUB1BVd6kPMeRwEYWSTV4RSdlG.jpg', 'Driving Miss Daisy tells the affecting story of the decades-long relationship between a stubborn Southern matriarch and her compassionate chauffeur. An iconic tale of pride, changing times and the transformative power of friendship, the play has warmed the hearts of millions of theatergoers worldwide.', NULL, NULL, 0.9943, 8.0, 0, 1.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
