INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10362, 41791, 'tt0102456', NULL, 'Mississippi Masala', 'Mississippi Masala', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/b2Gks4Stt98FRI5isaL6Wu1luhh.jpg', 'https://image.tmdb.org/t/p/original/PFrzqXuT0yEGEmcbXDwPOUKCsS.jpg', 'Years after her Indian family was forced to flee their Uganda home, twentysomething Mina finds herself co-operating a motel in the faraway land of Mississippi. Her passionate romance with charming Black carpet cleaner Demetrius challenges the prejudices of their conservative families and exposes the rifts between the region''s Indian and African-American communities.', NULL, NULL, 2.0514, 6.385, 0, 3.02666666666666683e+00, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10363, 18402, 'tt0114496', NULL, 'Something to Talk About', 'Something to Talk About', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/a52KpsmvLNdTdmDzw1fUrJONpfH.jpg', 'https://image.tmdb.org/t/p/original/cnUl10UxyT6yluGckYHwr7vycx7.jpg', 'Grace King Bichon, who is managing her father''s riding-stable, discovers that her husband Eddie is deceiving her with another woman. After confronting him in the middle of the night on the streets of their small home town, she decides to stay at her sister Emma Rae''s house for a while to make up her mind. Breaking out of her everyday life, she starts to question the authority of everyone.', NULL, NULL, 3.481, 5.623, 0, 2.02, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10364, 39279, 'tt1832979', NULL, 'Hart of Dixie', 'Hart of Dixie', 'tv', 2011, 'https://image.tmdb.org/t/p/w500/xOwH2ZUtdzqeat5RhiD3oes2ASx.jpg', 'https://image.tmdb.org/t/p/original/mEWt9LtHBQWopU3tC3I5h6lxHzP.jpg', 'New Yorker Zoe Hart has it all figured out - after graduating top of her class from medical school, she''ll follow in her father''s footsteps and become a cardio-thoracic surgeon. But when her dreams fall apart, Zoe decides to work at a small practice in Bluebell, Alabama.', NULL, NULL, 19.6995, 7.26, 0, 3.0166666666666666e+00, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10365, 24438, 'tt1314228', NULL, 'Did You Hear About the Morgans?', 'Did You Hear About the Morgans?', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/zNRLfwUGKaSQEDvOKlIOLGn8qRk.jpg', 'https://image.tmdb.org/t/p/original/4ctxEEXIDLRawB4To5ntzhbVqln.jpg', 'New Yorkers Paul and Meryl Morgan seem to have it all -- except that their marriage is crumbling around them. But their romantic woes are small compared to the trouble they find themselves in after witnessing a murder. To protect them from an assassin, federal agents whisk away Paul and Meryl to a small town in Wyoming, where their marriage will crash and burn, or their passion will reignite.', NULL, NULL, 3.6617, 5.389, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10366, 1325678, 'tt31727267', NULL, 'Sarah''s Oil', 'Sarah''s Oil', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/Av1CK61z33v2OBFLD1yF5rdRxQ1.jpg', 'https://image.tmdb.org/t/p/original/43vbVQDJlY7VoY3VPo8MipicxXk.jpg', 'Sarah Rector, a Black girl born in early 20th-century Oklahoma Indian Territory, believes there is oil beneath the barren land she’s allotted, and her faith proves right. As greedy oil sharks close in, Sarah turns to family, friends, and some Texas wildcatters to maintain control of her oil-rich land, eventually becoming among the nation''s first Black female millionaires—at eleven years old.', NULL, NULL, 6.857, 7.833, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
