INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10368, 6620, 'tt0047437', NULL, 'Sabrina', 'Sabrina', 'movie', 1954, 'https://image.tmdb.org/t/p/w500/e1Po9NDrH7IJZhv89467gJH5FS0.jpg', 'https://image.tmdb.org/t/p/original/3y8NgBIey8sivJAHaeIiyOnkDOz.jpg', 'After two years in Paris, chauffeur''s daughter Sabrina returns home elegantly transformed and immediately catches the attention of David, the playboy son of her father''s rich employers. David woos and wins Sabrina, who has always been in love with him, however their romance is threatened by David''s serious older brother Linus, who runs the family business and is relying on David to marry an heiress in order for a crucial merger to take place.', NULL, NULL, 5.1857, 7.504, 0, 6.51, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
