INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10375, 293399, 'tt0100497', NULL, 'Rising Son', 'Rising Son', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/11f1hCoLSvRhGNUWL9fnJv1puW9.jpg', 'https://image.tmdb.org/t/p/original/kW701TJsOhhDygO3irZw7qMcbMA.jpg', 'Gus Robinson loves three things: his job, family, and country; but suddenly he''s losing all three. When his factory shuts down, Gus faces unemployment. It''s a time of change for his wife Martha and son Charlie as they reassess a world Gus barely recognizes. But through the nightmare, one dream they cannot take away from him; the reason he will continue to fight: his son, Charlie.', NULL, NULL, 1.2843, 6.222, 0, 6.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
