INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10397, 72636, 'tt7222086', NULL, 'Made in Abyss', 'メイドインアビス', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/n30CBH4BoN5Z34tCpOWIPGJYOaS.jpg', 'https://image.tmdb.org/t/p/original/uzp513qTcHsAavlCJ58x5d73bzy.jpg', 'Located in the center of a remote island, the Abyss is the last unexplored region, a huge and treacherous fathomless hole inhabited by strange creatures where only the bravest adventurers descend in search of ancient relics. In the upper levels of the Abyss, Riko, a girl who dreams of becoming an explorer, stumbles upon a mysterious little boy.', NULL, NULL, 22.1302, 8.339, 0, 9.51, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
