INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10399, 7342, 'tt0319970', NULL, 'Carrie', 'Carrie', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/knjeEeeyIwDkUtZwDfJOcUIuNdB.jpg', 'https://image.tmdb.org/t/p/original/8z5qtVE2N3AuA3bmvIQsI10Wjg8.jpg', 'An awkward, telekinetic teenage girl''s lonely life is dominated by relentless bullying at school and an oppressive religious fanatic mother at home. When her tormentors pull a humiliating prank at the senior prom, she unleashes a horrifying chaos on everyone, leaving nothing but destruction in her wake.', NULL, NULL, 3.3536, 6.156, 0, 7.51, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10400, 34164, 'tt0380113', NULL, 'Haibane Renmei', '灰羽連盟', 'tv', 2002, 'https://image.tmdb.org/t/p/w500/uSrIXnPIUkapk0JwMldDZTusl5O.jpg', 'https://image.tmdb.org/t/p/original/sC7DcOOWmQ2WNEVDjLY0t8rEwqS.jpg', 'A dream of falling from the sky...and then birth. Rakka is born from a large cocoon into the Old Home, greeted by a group of female beings with small wings on their backs and shining halos above their heads. Soon Rakka’s own wings grow, a halo is placed on her head and she is told that she must work in the nearby town of Grie. She soon realizes that the town and the entire world they live in are confined behind the Wall, a tall, impenetrable wall that none except the mysterious Toga are allowed to exit.', NULL, NULL, 8.3955, 7.729, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10401, 132664, 'tt15353550', NULL, 'The Heike Story', '平家物語', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/fCqeRND1KqfQblDDD50S0VGfNP8.jpg', 'https://image.tmdb.org/t/p/original/aex5nAt1YJyyFSFeL2xxyEnF9Wo.jpg', 'A young orphan named Biwa is taken in by the powerful Taira Clan—also known as the Heike—after their leader witnesses her extraordinary psychic abilities. Unfortunately, what she predicts is a future of bloodshed, violence, and civil war. Inspired by the 12th-century epic tale Heike Monogatari.', NULL, NULL, 10.7087, 7.323, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10402, 74091, 'tt7790776', NULL, 'Land of the Lustrous', '宝石の国', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/4xCCKt34QfU0krs1XKsQI4152sE.jpg', 'https://image.tmdb.org/t/p/original/bkNvw8aaWYiOoUpx6mwTx6bDvEF.jpg', 'In the mysterious future, crystalline organisms called Gems inhabit a world that has been destroyed by six meteors. Each Gem is assigned a role in order to fight against the Lunarians, a species who attacks them in order to shatter their bodies and use them as decorations.

Phosphophyllite, also known as Phos, is a young and fragile Gem who dreams of helping their friends in the war effort. Instead, they are told to compile an encyclopedia because of their delicate condition. After begrudgingly embarking on this task, Phos meets Cinnabar, an intelligent gem who has been relegated to patrolling the isolated island at night because of the corrosive poison their body creates. After seeing how unhappy Cinnabar is, Phos decides to find a role that both of the rejected Gems can enjoy. Can Phos''s seemingly mundane assignment lead both Phos and Cinnabar to the fulfillment they desire?', NULL, NULL, 5.6471, 8.038, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10403, 34166, 'tt0433498', NULL, 'Kino''s Journey', 'キノの旅', 'tv', 2003, 'https://image.tmdb.org/t/p/w500/FKUT397b6Z2P2raqw1CjGQGisZ.jpg', 'https://image.tmdb.org/t/p/original/uHXZ5bUCiYZkjttnYIAYjghANRi.jpg', 'In Kino''s Journey, the protagonist, Kino, accompanied by a talking motorcycle named Hermes, travels through a mystical world of many different countries and forests, each unique in its customs and people. She only spends three days and two nights in every town, without exception, on the principle that three days is enough time to learn almost everything important about a place, while leaving time to explore new lands.', NULL, NULL, 7.0419, 7.8, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10404, 238151, 'tt29629770', NULL, 'Carol & the End of the World', 'Carol & the End of the World', 'tv', 2023, 'https://image.tmdb.org/t/p/w500/eqXQL8XGvL2tn2NfXKirBHQKo2d.jpg', 'https://image.tmdb.org/t/p/original/nUaOYBs1z1L3hx1ZuUNanXaKwxN.jpg', 'As a planetary apocalypse looms, a woman struggling to embrace end-times chaos searches for meaning in her last months on Earth.', NULL, NULL, 9.8739, 7.341, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10405, 60811, 'tt3592032', NULL, 'Ping Pong the Animation', 'ピンポン THE ANIMATION', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/frgVn3ww547TVQH8vS2bWKZnEBu.jpg', 'https://image.tmdb.org/t/p/original/1rEPk87q49PspQmBJ74bwsXBVkH.jpg', 'Makoto ''Smile'' Tsukimoto and his friend Yutaka ''Peco'' Hoshino have been playing table tennis together since they were kids, but as they enter high school, they find that the game, and how they see it, has changed. Peco, brimming with confidence and energy, wants to be the best in the world, but the reserved Smile has little fighting spirit and doesn''t want to sacrifice others'' happiness just to win, despite his innate talent. As the two grow, and experience the ups and downs of the sport – and life – they try to figure out exactly who they really are and what drives them to play.', NULL, NULL, 9.7239, 8.2, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
