INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (10431, 14805, 'tt0211938', NULL, 'Bait', 'Bait', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/jon5ux36iUn6GnntxkZaNtB6AZT.jpg', 'https://image.tmdb.org/t/p/original/4gd9LCL1l8j88psOKbXtuAbTRlq.jpg', 'Landing in jail for a petty theft crime, Alvin finds himself sharing a cell with John Jaster, the incarcerated half of the pair of high-tech thieves responsible for the missing gold. His partner, Bristol, is still at large. Alvin wants only to get out of prison and start fresh with his girlfriend, Lisa, and when the Feds, led by U.S. Treasury investigator Clenteen, set him loose on a sketchy deal, he thinks his luck has changed. Alvin has his freedom and the Feds have found their bait.', NULL, NULL, 3.2328, 5.724, 0, 1.01, '2026-08-18 01:44:45', '2026-08-18 01:44:45');
