UPDATE "recommendations" SET "tmdb_id"=10150, "imdb_id"='tt0084237', "igdb_id"=NULL, "title"='The Last Unicorn', "original_title"='The Last Unicorn', "media_type"='movie', "release_year"=1982, "poster_url"='https://image.tmdb.org/t/p/w500/MRHFtXTjxC74MGCzHACcuqvHiw.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fwxOQkzYtRVKs3kzcyukdbsyIuh.jpg', "overview"='A unicorn learns from a riddle-speaking butterfly that she is supposedly the last of her kind, all the others having been herded away by the monstrous Red Bull. The unicorn sets out to discover the truth behind the butterfly''s words. She is eventually joined on her quest by Schmendrick, a second-rate magician, and Molly Grue, a middle-aged woman who dreamed all her life of seeing a unicorn. Their journey leads them far from home, all the way to the castle of King Haggard.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.802, "vote_average"=7.283, "is_ambiguous"=0, "evidence_score"=4.21794594594594585e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=159;
UPDATE "recommendations" SET "tmdb_id"=10601, "imdb_id"='tt0316396', "igdb_id"=NULL, "title"='Peter Pan', "original_title"='Peter Pan', "media_type"='movie', "release_year"=2003, "poster_url"='https://image.tmdb.org/t/p/w500/6QdU3TZZrIvXFzoHOwafZAynFjB.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/zyWbOvKCdA9V9P5xuUG2eiPYsUo.jpg', "overview"='In stifling Edwardian London, Wendy Darling mesmerizes her brothers every night with bedtime tales of swordplay, swashbuckling and the fearsome Captain Hook. But the children become the heroes of an even greater story, when Peter Pan flies into their nursery one night and leads them over moonlit rooftops through a galaxy of stars and to the lush jungles of Neverland.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.1714, "vote_average"=7.13, "is_ambiguous"=0, "evidence_score"=1.49841666666666668e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=160;
UPDATE "recommendations" SET "tmdb_id"=70785, "imdb_id"='tt5421602', "igdb_id"=NULL, "title"='Anne with an E', "original_title"='Anne with an E', "media_type"='tv', "release_year"=2017, "poster_url"='https://image.tmdb.org/t/p/w500/6P6tXhjT5tK3qOXzxF9OMLlG7iz.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ywQtHG17LZhAFZyZtBflhtFMtJ7.jpg', "overview"='A coming-of-age story about an outsider who, against all odds and numerous challenges, fights for love and acceptance and for her place in the world. The series centers on a young orphaned girl in the late 1890s, who, after an abusive childhood spent in orphanages and the homes of strangers, is mistakenly sent to live with an elderly woman and her aging brother. Over time, 13-year-old Anne will transform their lives and eventually the small town in which they live with her unique spirit, fierce intellect and brilliant imagination.', "external_url"=NULL, "platforms"=NULL, "popularity"=27.7123, "vote_average"=8.65, "is_ambiguous"=0, "evidence_score"=8.90500000000000113e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=165;
UPDATE "recommendations" SET "tmdb_id"=11236, "imdb_id"='tt0108071', "igdb_id"=NULL, "title"='The Secret Garden', "original_title"='The Secret Garden', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/zf6h5dJ7wVG7LqMO9dhHGHVejzj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8s7FJ9dHXgeFZdvxfjPmrrJh6EC.jpg', "overview"='A young British girl born and reared in India loses her neglectful parents in an earthquake. She is returned to England to live at her uncle''s castle. Her uncle is very distant due to the loss of his wife ten years before. Neglected once again, she begins exploring the estate and discovers a garden that has been locked and forgotten. Aided by one of the servants'' boys, she begins restoring the garden, and eventually discovers some other secrets of the manor.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.0266, "vote_average"=7.425, "is_ambiguous"=0, "evidence_score"=3.75505882352941142e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=166;
