UPDATE "recommendations" SET "tmdb_id"=2750, "imdb_id"='tt0274309', "igdb_id"=NULL, "title"='24 Hour Party People', "original_title"='24 Hour Party People', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/8f50NQ1wz6hdxfCISCPV8XQ6DII.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ucRD8UUr5tllltg3ZTWoXOyPXyJ.jpg', "overview"='Manchester, 1976. Tony Wilson is an ambitious but frustrated local TV news reporter looking for a way to make his mark. After witnessing a life-changing concert by a band known as the Sex Pistols, he persuades his station to televise one of their performances, and soon Manchester''s punk groups are clamoring for him to manage them. Riding the wave of a musical revolution, Wilson and his friends create the legendary Factory Records label and The Hacienda club.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.7527, "vote_average"=6.976, "is_ambiguous"=0, "evidence_score"=15.18, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=585;
