UPDATE "recommendations" SET "tmdb_id"=627, "imdb_id"='tt0117951', "igdb_id"=NULL, "title"='Trainspotting', "original_title"='Trainspotting', "media_type"='movie', "release_year"=1996, "poster_url"='https://image.tmdb.org/t/p/w500/1jUC02qsqS2NxBMFarbIhcQtazV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dkfBKDUIWP1peEszdqK10MkMZCP.jpg', "overview"='Heroin addict Mark Renton stumbles through bad ideas and sobriety attempts with his unreliable friends --Sick Boy, Begbie, Spud and Tommy. He also has an underage girlfriend, Diane, along for the ride. After cleaning up and moving from Edinburgh to London, Mark finds he can''t escape the life he left behind as Begbie and Sick Boy come knocking.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.3844, "vote_average"=7.958, "is_ambiguous"=0, "evidence_score"=5.93223214285714277e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=644;
UPDATE "recommendations" SET "tmdb_id"=8909, "imdb_id"='tt0493464', "igdb_id"=NULL, "title"='Wanted', "original_title"='Wanted', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/njy7Pz7ZHZceO7lNfGIHKphY8Hd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vjwuT8EzWY96W6nrJKZNI2WJU87.jpg', "overview"='Doormat Wesley Gibson is an office worker whose life is going nowhere. He meets an attractive woman named Fox and discovers that his recently murdered father - whom Wesley never knew - belonged to the Fraternity, a secret society of assassins which takes its orders from Fate itself. Fox and Sloan, the Fraternity''s leader, teach Wesley, through intense training, to tap into dormant powers and hone his innate killing skills. Though he enjoys his newfound abilities, he begins to suspect that there is more to the Fraternity than meets the eye.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.767, "vote_average"=6.529, "is_ambiguous"=0, "evidence_score"=14.928, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=648;
UPDATE "recommendations" SET "tmdb_id"=332562, "imdb_id"='tt1517451', "igdb_id"=NULL, "title"='A Star Is Born', "original_title"='A Star Is Born', "media_type"='movie', "release_year"=2018, "poster_url"='https://image.tmdb.org/t/p/w500/wrFpXMNBRj2PBiN4Z5kix51XaIZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dDYpjrwh1wNVQk0rEpc9P81wQt4.jpg', "overview"='Seasoned musician Jackson Maine discovers — and falls in love with — struggling artist Ally. She has just about given up on her dream to make it big as a singer — until Jack coaxes her into the spotlight. But even as Ally''s career takes off, the personal side of their relationship is breaking down, as Jack fights an ongoing battle with his own internal demons.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.5248, "vote_average"=7.491, "is_ambiguous"=0, "evidence_score"=8.145, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=652;
UPDATE "recommendations" SET "tmdb_id"=37735, "imdb_id"='tt1282140', "igdb_id"=NULL, "title"='Easy A', "original_title"='Easy A', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/v5f1qO6NJnxWgONgkYg21TW39DT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/30rvmoEBqovm723agDJ3QddWXcY.jpg', "overview"='Olive, an average high school student, sees her below-the-radar existence turn around overnight once she decides to use the school''s gossip grapevine to advance her social standing. Now her classmates are turning against her and the school board is becoming concerned, including her favorite teacher and the distracted guidance counselor. With the support of her hilariously idiosyncratic parents and a little help from a long-time crush, Olive attempts to take on her notorious new identity and crush the rumor mill once and for all.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.2755, "vote_average"=6.8, "is_ambiguous"=0, "evidence_score"=1.58063636363636348e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=654;
UPDATE "recommendations" SET "tmdb_id"=10096, "imdb_id"='tt0337563', "igdb_id"=NULL, "title"='13 Going on 30', "original_title"='13 Going on 30', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/iNZdSIfhSCMtRILDNyhLn8UKeSG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ld7UTOGzZSxIMbuYsb6eQ6QdN4h.jpg', "overview"='After total humiliation at her thirteenth birthday party, Jenna Rink wants to just hide until she''s thirty. Thanks to some magic wishing dust, Jenna''s prayer has been answered. With a knockout body, a fabulous wardrobe, an athlete boyfriend, a dream job, and superstar friends, this can''t be a better life. But soon Jenna realizes that adult life isn’t as easy as she hoped for.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.9045, "vote_average"=6.777, "is_ambiguous"=0, "evidence_score"=2.40857142857142854e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=667;
