UPDATE "recommendations" SET "tmdb_id"=49494, "imdb_id"='tt1034389', "igdb_id"=NULL, "title"='The Eagle', "original_title"='The Eagle', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/mbsdwO4lfIARqt35VVTM0UlYkhZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/k78NOxPHrWCDmBnVx0fux37Vv05.jpg', "overview"='In 140 AD, twenty years after the unexplained disappearance of the entire Ninth Legion in the mountains of Scotland, young centurion Marcus Aquila arrives from Rome to solve the mystery and restore the reputation of his father, the commander of the Ninth. Accompanied only by his British slave Esca, Marcus sets out across Hadrian''s Wall into the uncharted highlands of Caledonia - to confront its savage tribes, make peace with his father''s memory, and retrieve the lost legion''s golden emblem, the Eagle of the Ninth.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.4629, "vote_average"=6.236, "is_ambiguous"=0, "evidence_score"=13.7025, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=730;
