UPDATE "recommendations" SET "tmdb_id"=9886, "imdb_id"='tt0113481', "igdb_id"=NULL, "title"='Johnny Mnemonic', "original_title"='Johnny Mnemonic', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/iH8Jgi8qvb7pnBfI8fVGaUbyRna.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7FRYVIF2hnh1IbPtqMgF5iygdjz.jpg', "overview"='In a dystopian 2021, Johnny is a data trafficker who has an implant that allows him to securely store data too sensitive for regular computer networks. On one delivery run, he accepts a package that not only exceeds the implant''s safety limits—and will kill him if the data is not removed in time—but also contains information far more important and valuable than he had ever imagined. On a race against time, he must avoid the assassins sent to kill him and remove the data before it, too, ends his life.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3516, "vote_average"=5.758, "is_ambiguous"=0, "evidence_score"=2.09777777777777778e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=785;
