UPDATE "recommendations" SET "tmdb_id"=671, "imdb_id"='tt0241527', "igdb_id"=NULL, "title"='Harry Potter and the Philosopher''s Stone', "original_title"='Harry Potter and the Philosopher''s Stone', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1XAC6RPT01UX9EQGy2JVn5c8pgy.jpg', "overview"='Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths—and about the villain who''s to blame.', "external_url"=NULL, "platforms"=NULL, "popularity"=40.2884, "vote_average"=7.902, "is_ambiguous"=0, "evidence_score"=15.39125, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=811;
UPDATE "recommendations" SET "tmdb_id"=841, "imdb_id"='tt0087182', "igdb_id"=NULL, "title"='Dune', "original_title"='Dune', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/4kJmUCE7mkVJjXa7A0g2rY4IGTm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5wJ2tckpvwcxGCAgZiccodwEJpf.jpg', "overview"='In the year 10,191, the most precious substance in the universe is the spice Melange. The spice extends life. The spice expands consciousness. The spice is vital to space travel.  The spice exists on only one planet in the entire universe, the vast desert planet Arrakis, also known as Dune.  Its native inhabitants, the Fremen, have long held a prophecy that a man would come, a messiah who would lead them to true freedom.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.6554, "vote_average"=6.186, "is_ambiguous"=0, "evidence_score"=17.898, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=821;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=484, "title"='Silent Hill: Origins', "original_title"='Silent Hill: Origins', "media_type"='game', "release_year"=2007, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co2vyq.jpg', "backdrop_url"=NULL, "overview"='Silent Hill: Origins is the fifth installment in the Silent Hill survival horror series, and a prequel to the original game. As in the previous entries, the player move back and forth between nightmare and real versions of the town, gathering items used to solve puzzles and open up new areas. Monsters of various types provide obstacles and, in series tradition, are mostly disturbingly twisted versions of humanity. The main character can fight with his bare fists or use melee weapons. Unlike previous games in the series, melee weapons break after a time. There are also one-shot items that can be thrown and several guns. There is no HUD, but the edge of the screen turns red when the protagonist is near death.', "external_url"='https://www.igdb.com/games/silent-hill-origins', "platforms"='["PlayStation Portable", "PlayStation 2"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=1.36157142857142865e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-18 01:44:45' WHERE "id"=838;
