UPDATE "recommendations" SET "tmdb_id"=14161, "imdb_id"='tt1190080', "igdb_id"=NULL, "title"='2012', "original_title"='2012', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/zaqam2RNscH5ooYFWInV6hjx6y5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/x9GeCXTGiPcmQcCsd1yzbNnx3up.jpg', "overview"='Dr. Adrian Helmsley, part of a worldwide geophysical team investigating the effect on the earth of radiation from unprecedented solar storms, learns that the earth''s core is heating up. He warns U.S. President Thomas Wilson that the crust of the earth is becoming unstable and that without proper preparations for saving a fraction of the world''s population, the entire race is doomed. Meanwhile, writer Jackson Curtis stumbles on the same information. While the world''s leaders race to build "arks" to escape the impending cataclysm, Curtis struggles to find a way to save his family. Meanwhile, volcanic eruptions and earthquakes of unprecedented strength wreak havoc around the world.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.4766, "vote_average"=5.889, "is_ambiguous"=0, "evidence_score"=11.45375, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-18 01:44:45' WHERE "id"=3370;
