UPDATE "recommendations" SET "tmdb_id"=9408, "imdb_id"='tt0423294', "igdb_id"=NULL, "title"='Surf''s Up', "original_title"='Surf''s Up', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/tTDsCVlDA8QR4Dc6t6nERfwl5z.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/Y50RfoNVKIj9dSJavE8uBdN377.jpg', "overview"='With a documentary crew in tow, Cody Maverick—a young surfer from Antarctica—travels to the pacific for his first professional competition. Determined to earn respect and live up to his idol, Big Z, Cody pushes himself to the limit. But all that changes when an encounter with a laid-back local forces him to rethink his values.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.2625, "vote_average"=6.516, "is_ambiguous"=0, "evidence_score"=1.21990909090909092e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-18 01:44:45' WHERE "id"=3450;
UPDATE "recommendations" SET "tmdb_id"=9266, "imdb_id"='tt0300532', "igdb_id"=NULL, "title"='Blue Crush', "original_title"='Blue Crush', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/iZSw0JVG0cIFuZoTHuQU3nmGT4k.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xsVMKdSndUKid3Xm3Tudf5bcOlv.jpg', "overview"='Nothing gets between Anne Marie and her board. Living in a beach shack with three roommates, she is up before dawn every morning to conquer the waves and count the days until the Pipe Masters competition. Having transplanted herself to Hawaii with no one''s blessing but her own, Anne Marie finds all she needs in the adrenaline-charged surf scene - until pro quarterback Matt Tollman comes along...', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6737, "vote_average"=5.998, "is_ambiguous"=0, "evidence_score"=2.79284615384615371e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-18 01:44:45' WHERE "id"=3451;
