UPDATE "recommendations" SET "tmdb_id"=21, "imdb_id"='tt0060371', "igdb_id"=NULL, "title"='The Endless Summer', "original_title"='The Endless Summer', "media_type"='movie', "release_year"=1966, "poster_url"='https://image.tmdb.org/t/p/w500/jDdntrv2j64KB0Zpr63cko4Mebt.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uNRfK14Ga8Hwfqt07vo8nvWQN1i.jpg', "overview"='Bruce Brown''s The Endless Summer is one of the first and most influential surf movies of all time. The film documents American surfers Mike Hynson and Robert August as they travel the world during California’s winter (which, back in 1965 was off-season for surfing) in search of the perfect wave and ultimately, an endless summer.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9125, "vote_average"=7.162, "is_ambiguous"=0, "evidence_score"=1.10328571428571429e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-18 01:44:45' WHERE "id"=3454;
