UPDATE "recommendations" SET "tmdb_id"=404, "imdb_id"='tt0166896', "igdb_id"=NULL, "title"='The Straight Story', "original_title"='The Straight Story', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/tT9cMiVDdtlcdZxOoFy3VRmEoKk.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1S81PpyGwS8eVx4W75uSKzMw4B0.jpg', "overview"='Retired farmer and widower Alvin Straight learns one day that his distant brother Lyle has suffered a stroke and may not recover. Alvin is determined to make things right with Lyle while he still can, but his brother lives in Wisconsin, while Alvin is stuck in Iowa with no car and no driver''s license. He then has the idea of making the trip on his old lawnmower, thus beginning a picturesque and at times deeply spiritual odyssey.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.8547, "vote_average"=7.741, "is_ambiguous"=0, "evidence_score"=2.03082352941176473e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-18 01:44:45' WHERE "id"=4022;
