UPDATE "recommendations" SET "tmdb_id"=84175, "imdb_id"='tt2125435', "igdb_id"=NULL, "title"='Beasts of the Southern Wild', "original_title"='Beasts of the Southern Wild', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nQJmWekGYlXhezGUb21xFfEfwhH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7LWLPvyfLSb2oOlgWwAwUqA8uKo.jpg', "overview"='Hushpuppy, an intrepid six-year-old girl, lives with her father, Wink, in ''the Bathtub'', a southern Delta community at the edge of the world. Wink’s tough love prepares her for the unraveling of the universe—for a time when he’s no longer there to protect her. When Wink contracts a mysterious illness, nature flies out of whack—temperatures rise and the ice caps melt, unleashing an army of prehistoric creatures called aurochs. With the waters rising, the aurochs coming, and Wink’s health fading, Hushpuppy goes in search of her lost mother.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.2017, "vote_average"=6.841, "is_ambiguous"=0, "evidence_score"=1.87022222222222218e+01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-18 01:44:45' WHERE "id"=5468;
