UPDATE "recommendations" SET "tmdb_id"=1042, "imdb_id"='tt0205410', "igdb_id"=NULL, "title"='Revolutionary Girl Utena', "original_title"='少女革命ウテナ', "media_type"='tv', "release_year"=1997, "poster_url"='https://image.tmdb.org/t/p/w500/riqymWBPqKmWpIvS3lVDYjZhwQ5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/802aSsZzIyOhbaL1bt19gp0RVYq.jpg', "overview"='"Never lose that strength or nobility, even when you grow up." When Utena was just a child and in the depths of sorrow, she found salvation in those words. They were the words of a prince, who bestowed upon her both a ring and the promise that it would lead her to him again. She never forgot the encounter. Now a teenager, Utena attends the prestigious Ohtori Academy; however, her strong sense of chivalry soon places her at odds with the student council and thrusts her into a series of mysterious and dangerous duels against its members.', "external_url"=NULL, "platforms"=NULL, "popularity"=22.6728, "vote_average"=8.107, "is_ambiguous"=0, "evidence_score"=2.02, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-18 01:44:45' WHERE "id"=5616;
UPDATE "recommendations" SET "tmdb_id"=898, "imdb_id"='tt0055798', "igdb_id"=NULL, "title"='Birdman of Alcatraz', "original_title"='Birdman of Alcatraz', "media_type"='movie', "release_year"=1962, "poster_url"='https://image.tmdb.org/t/p/w500/6EODLN11HTX4l2cmakAhWIoJLF.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1J6QXImtqIQxiOdVTonLV5IbRwA.jpg', "overview"='After killing a prison guard, convict Robert Stroud faces life imprisonment in solitary confinement. Driven nearly mad by loneliness and despair, Stroud''s life gains new meaning when he happens upon a helpless baby sparrow in the exercise yard and nurses it back to health. Despite having only a third grade education, Stroud goes on to become a renowned ornithologist and achieves a greater sense of freedom and purpose behind bars than most people find in the outside world.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9648, "vote_average"=7.497, "is_ambiguous"=0, "evidence_score"=392.755, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-18 01:44:45' WHERE "id"=5668;
UPDATE "recommendations" SET "tmdb_id"=102651, "imdb_id"='tt1587310', "igdb_id"=NULL, "title"='Maleficent', "original_title"='Maleficent', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/ik8PugpL41s137RAWEGTAWu0dPo.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bNiiUCQUD7ij5Ybh2GoWSZwqAb1.jpg', "overview"='A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land. She rises to be the land''s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King''s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom – and to Maleficent''s true happiness as well.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.5323, "vote_average"=7.088, "is_ambiguous"=0, "evidence_score"=1.24133333333333339e+01, "created_at"='2026-07-30 18:28:39', "updated_at"='2026-08-18 01:44:45' WHERE "id"=5674;
