UPDATE "recommendations" SET "tmdb_id"=488623, "imdb_id"='tt7057496', "igdb_id"=NULL, "title"='Forgotten', "original_title"='기억의 밤', "media_type"='movie', "release_year"=2017, "poster_url"='https://image.tmdb.org/t/p/w500/cBgj41y1RvmW1zJCEX0uNWL0UjW.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/tGFII2hY0O0qXPAPGE1fBDOONQJ.jpg', "overview"='Jin-seok, 21-year-old, moves into a new house with his family. He suffers from a slight schizophrenia but he carries an ordinary life under the warm care of the family. His older brother Yu-seok is a decent college student, a mentor, and role model for Jin-seok.  One night, his beloved brother is kidnapped by unidentified assailants before Jin-seok''s eye. Jin-seok can’t recognize their faces, but can remember only the VIN that matches with no car. After long silence of 19 days, suddenly Yu-seok returns home, but remembers nothing which had happened in the meantime. And soon Jin-seok feels Yu-seok is a total stranger.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.5906, "vote_average"=7.882, "is_ambiguous"=0, "evidence_score"=4.51500000000000056e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-18 01:44:45' WHERE "id"=6167;
