UPDATE "recommendations" SET "tmdb_id"=568160, "imdb_id"='tt9426210', "igdb_id"=NULL, "title"='Weathering with You', "original_title"='天気の子', "media_type"='movie', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/qgrk7r1fV4IjuoeiGS5HOhXNdLJ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ize3ZieqSy0TCWljmVoEiy8fSFS.jpg', "overview"='The summer of his high school freshman year, Hodaka runs away from his remote island home to Tokyo, and quickly finds himself pushed to his financial and personal limits. The weather is unusually gloomy and rainy every day, as if taking its cue from his life. After many days of solitude, he finally finds work as a freelance writer for a mysterious occult magazine. Then, one day, Hodaka meets Hina on a busy street corner. This bright and strong-willed girl possesses a strange and wonderful ability: the power to stop the rain and clear the sky.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.2838, "vote_average"=7.976, "is_ambiguous"=0, "evidence_score"=10.448, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-18 01:44:45' WHERE "id"=6274;
