UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=393025, "title"='Final Fantasy VII', "original_title"='Final Fantasy VII', "media_type"='game', "release_year"=1997, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/cobny6.jpg', "backdrop_url"=NULL, "overview"='Final Fantasy VII (note: this is the original Japan-exclusive version) is a role-playing game set in a post-modern, steampunk world where technology and fantasy elements coexist. Players control Cloud Strife, an ex-soldier who joins the eco-terrorist group AVALANCHE to oppose Shinra Inc., a corporation draining the planet''s life energy. The game features turn-based combat with an active time element, a customizable Materia system for abilities, and unique Limit Break attacks for each character. Players explore 3D environments, engage in various mini-games, and uncover a complex plot involving Cloud''s mysterious past and a powerful threat to the world. As the story progresses, players gain access to different vehicles, allowing them to explore new areas and uncover additional content.', "external_url"='https://www.igdb.com/games/final-fantasy-vii--12', "platforms"='["PlayStation"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=9.26000000000000156e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-18 01:44:45' WHERE "id"=6467;
