UPDATE "recommendations" SET "tmdb_id"=99117, "imdb_id"='tt2175535', "igdb_id"=NULL, "title"='Adam Chaplin', "original_title"='Adam Chaplin', "media_type"='movie', "release_year"=2011, "poster_url"='https://image.tmdb.org/t/p/w500/nEUn35sNCZWkaROnKKZXCOrwsr2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vEfBwIp8huLWJElhOP8krbTTK2G.jpg', "overview"='Set in the fictional country of Heaven Valley, the film is the story of a man, Adam, who following the suspicious death of his wife begins to investigate her murder and in doing so, discovers the involvement of local mafia boss: Denny Richards.  Unable to trust the police, corrupt and controlled by Denny, Adam, consumed by anger, summons a demon who offers him superhuman strength and dark powers. The demon follows him during his trip, promising to lead Adam to the door of the murderer if he does everything the demon asks.  This unleashes a bloody war that will bring Adam, the demon on his side, against the police department with all its dark allies. The fight begins and it will be extreme!', "external_url"=NULL, "platforms"=NULL, "popularity"=2.3255, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-08-06 03:21:21', "updated_at"='2026-08-18 01:44:45' WHERE "id"=7824;
